def ev(c, quote, field='passage_text', choice=None, supplement=None, note=None):
    if supplement:
        path=BASE/supplement; text=path.read_text(); pointer=None
    else:
        path=BASE/f'{c}.json'; text=SOURCES[c][field]; pointer='/'+field
        if choice is not None: text=text[choice-1]; pointer+=f'/{choice-1}'
    assert quote in text, (c,field,quote)
    start=text.index(quote); key=(str(path.relative_to(ROOT)),pointer,start,len(quote))
    if key in link_cache: return link_cache[key]
    eid=f'EA{len(links)+1:04d}'; link_cache[key]=eid
    links.append({'evidence_id':eid,'source_path':str(path.relative_to(ROOT)),
                  'source_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),
                  'json_pointer':pointer,'char_start':start,'char_end_exclusive':start+len(quote),
                  'paragraph_index_1_based':text[:start].count('\n\n')+1,
                  'line_start_1_based':text[:start].count('\n')+1,
                  'exact_quote':quote,'case_context':c,'note':note})
    return eid

def E(c,*quotes): return [ev(c,q) for q in quotes]

def rel(pid,status,why,evidence,subtype=None,role=None):
    return {'pattern_id':pid,'subtype_id':subtype,'decision':status,'reason':why,
            'evidence_ids':evidence,'role':role,
            'subtype_limit':None if subtype else '하위형까지 일치한다고 확정하지 않음; 상위 조작 또는 경계만 판정'}

def choice(c,n,status,operation,premise,middle,difference,conclusion,quotes):
    return {'choice_number':n,'choice_text':SOURCES[c]['choices'][n-1],
            'content_status':status,'item_transformation':operation,
            'minimum_argument':{'source_premise':premise,'needed_intermediate_inference':middle,
              'difference_or_match':difference,'conclusion':conclusion},
            'evidence_ids':E(c,*quotes)+[ev(c,SOURCES[c]['choices'][n-1],'choices',n)]}

def item(c,used,unused,read_stage,choice_stage,alternative,unnecessary,choices,relations,residual,boundary):
    raw=RAW[c]
    r={'record_type':'item_application','schema_version':'external-application-1.0',
       'group_id':raw['group_id'],'case_id':c,'stem':SOURCES[c]['stem'],
       'source_path':f'data/기본기_연구/prepared_backlog/blind_sources/{c}.json',
       'initial_solution':raw,'answer_status':'원문 기반 선택; 공식 정답 미대조; 정답률 산출 안 함',
       'information_actually_used':used,'present_but_not_used':unused,
       'recognition_during_reading':read_stage,'recognition_after_choices':choice_stage,
       'alternative_valid_route':alternative,'unnecessary_procedures':unnecessary,
       'choice_analyses':choices,'pattern_decisions':relations,
       'residual_candidate_ids':residual,'boundary_or_counterexample':boundary}
    considered={x['pattern_id'] for x in relations}
    r['not_applicable_patterns']=[{'pattern_id':card['pattern_id'],
        'reason':NON_APPLICATION[card['pattern_id']]}
        for card in BOOK['cards'] if card['pattern_id'] not in considered]
    r['evidence_ids']=list(dict.fromkeys([ev(c,SOURCES[c]['stem'],'stem')]+[x for ch in choices for x in ch['evidence_ids']]+[x for a in relations for x in a['evidence_ids']]))
    records.append(r)

def passage(g,functions,used,unused,relations,defects):
    c=GROUPS[g][0]
    records.append({'record_type':'passage_application','group_id':g,'case_ids':GROUPS[g],
      'source_path':f'data/기본기_연구/prepared_backlog/blind_sources/{c}.json',
      'functional_organization':functions,'structures_used_by_items':used,
      'structures_not_used_or_only_background':unused,'pattern_decisions':relations,
      'source_defects_and_limits':defects,
      'evidence_ids':list(dict.fromkeys([x for a in functions for x in a['evidence_ids']]+[x for a in relations for x in a['evidence_ids']]))})

def fun(c,loc,function,*quotes): return {'location':loc,'function':function,'evidence_ids':E(c,*quotes)}

