item('YT',['P4 조건 조합 규칙 전체','보기의 위티 모형 부합·네 조합·집단별 반응'],['P1 공포 수준 실험','P3 동호회 예시','연구 연대'],
 '높은 위협 안에서는 효능감 수준이 두 통제 반응을 구별하고, 낮은 위협 안에서는 효능감 차이가 결과에 남지 않는다.',
 '집단3/4의 효능감은 각각 높음/낮음으로 복원 가능하다. 집단1/2의 효능감은 무반응만으로 각각 배정할 수 없다.',
 '집단3 위험 통제와 집단4 공포 통제에 대응하는 두 문장만 회수해 ⑤를 결정 가능하다.',
 ['집단1의 효능감을 높음으로 임의 지정하지 않음','집단번호를 발생 순서로 읽지 않음','무반응을 공포 통제로 동일시하지 않음'],[
 choice('YT',1,'참','반응 결과에서 위협 조건 역추론','모형에서 무반응은 낮은 위협에 해당한다.','보기는 모형 부합과 네 조합을 명시한다.','집단1은 낮은 위협이다. 효능감까지는 확정하지 않는다.','부적절 추론이 아니다.',['위협의 수준이 낮으면','효능감의 수준에 관계없이 공포 소구에 대한 반응이 없게 된다.']),
 choice('YT',2,'참','위험 통제에서 조합 조건 복원','위협·효능감 모두 높으면 위험 통제이다.','보기의 폐쇄 모형에서는 이 반응이 해당 조합에 대응한다.','집단3의 효능감은 높다.','부적절 추론이 아니다.',['위협과 효능감의 수준이 모두 높을 때에는 위험 통제 반응']),
 choice('YT',3,'참','공포 통제 조합의 두 수준 비교','위협 높음·효능감 낮음이면 공포 통제이다.','집단4에서 두 수준은 다르다.','조합을 보존한다.','부적절 추론이 아니다.',['위협의 수준은 높지만 효능감의 수준이 낮을 때에는 공포 통제 반응']),
 choice('YT',4,'참','각 결과에서 복원한 같은 요인 비교','무반응은 낮은 위협, 공포 통제는 높은 위협이다.','집단2와4의 위협 수준은 다르다.','효능감이 아니라 같은 위협 축을 비교한다.','부적절 추론이 아니다.',['위협의 수준이 낮으면','위협의 수준은 높지만 효능감의 수준이 낮을 때에는 공포 통제 반응']),
 choice('YT',5,'거짓','서로 다른 결과 조건의 효능감 값을 동일화','위험 통제는 효능감 높음, 공포 통제는 효능감 낮음이다.','집단3과4는 위협은 같고 효능감은 다르다.','같은 위협을 같은 효능감으로 이동시켰다.','선택한다.',['위협과 효능감의 수준이 모두 높을 때에는 위험 통제 반응','위협의 수준은 높지만 효능감의 수준이 낮을 때에는 공포 통제 반응'])],
 [rel('P02','적용','⑤에서 집단3/4의 공통 위협과 다른 효능감을 같은 축끼리 비교한다. 그러나 결과에서 조건을 역으로 복원하는 절차 전체는 설명하지 못한다.',E('YT','위협과 효능감의 수준이 모두 높을 때','위협의 수준은 높지만 효능감의 수준이 낮을 때'),role='⑤ 차이 비교'),
  rel('P04','구조상 존재','조합 요건은 있다. 결과→가능 조합의 역추론을 필요조건 결손 확인과 같게 세지 않는다.',E('YT','위협과 효능감의 수준이 모두 높을 때')),
  rel('S04','경계·비적용','무반응에는 두 효능감 후보가 남지만 복수 적합/무적합이라는 유보 원인을 비교하는 장면은 없다. 기존 후보 집합 하위형의 직접 반복으로 확정하지 않는다.',E('YT','효능감의 수준에 관계없이 공포 소구에 대한 반응이 없게 된다.')),
  rel('P07','경계·비적용','집단1~4는 병렬 실험 조건이다. 번호가 단계 순서를 증명하지 않는다.',E('YT','위협의 수준이 낮으면'))],
 ['R08'], '집단3에서 효능감 높음은 복원되지만 집단1 무반응에서 효능감 수준은 둘 중 하나로만 남는다. 따라서 모든 결과를 단일 원인으로 역추론하는 요령은 이 문항 자체에서 반례를 갖는다.')

item('YU',['P2 치우치다/부르다의 용례','P3 겪다/보내다의 용례','P4 영향을 주다의 용례'],['공포 이론의 타당성과 네 조건의 역추론'],
 '각 동사의 목적어·문장 기능을 읽을 수 있다. ㉤의 영향은 긍정적 도움으로 제한되지 않는다.',
 '⑤는 중립적인 영향 주다를 도움·이바지의 기여로 바꿔 의미가 좁아진다.',
 '⑤를 아무 영향을 __에 넣어 중립적 인과와 도움 의미의 차이를 설명하면 된다.',
 ['권고 내용 자체가 유익하다는 이유로 기여를 정답 치환으로 받아들이지 않음'],[
 choice('YU',1,'치환 적합','한 측면 집중을 편향으로 재진술','감정적 측면에만 치우쳤다고 비판한다.','편향은 한쪽으로 치우침이다.','문맥 뜻을 보존한다.','선택하지 않는다.',['감정적 측면에만 ㉠ 치우쳤다고']),
 choice('YU',2,'치환 적합','반응 유형의 이름 붙임','반응을 공포/위험 통제 반응이라 불렀다.','명명은 이름 붙임이다.','호칭 기능을 보존한다.','선택하지 않는다.',['인지적 반응을 ‘위험 통제 반응’이라 ㉡ 불렀다.']),
 choice('YU',3,'치환 적합','위험을 겪음을 경험으로 재진술','위험을 자신이 겪을 수 있다고 느낀다.','위험을 경험함과 같은 뜻이다.','문맥 뜻을 보존한다.','선택하지 않는다.',['위험을 자신이 ㉢ 겪을 수 있는 것이고']),
 choice('YU',4,'치환 적합','안내문 전달을 발송으로 재진술','회원에게 안내문을 보냈다.','문서를 보내는 행위는 발송이다.','문맥 뜻을 보존한다.','선택하지 않는다.',['안내문을 ㉣ 보냈다고 하자.']),
 choice('YU',5,'치환 부적합','중립적 영향을 유익한 기여로 좁히기','자신에게 아무 영향을 주지 않는다고 느낀다.','기여는 어떤 결과에 도움·이바지한다는 뜻을 더한다.','위협의 영향 일반을 도움으로 제한했다.','선택한다.',['자신에게 아무 영향을 ㉤ 주지 않는다고 느껴'])],
 [rel('P05','적용','주다의 뜻을 목적어 아무 영향에 붙여 치환 후보의 의미 성분과 비교한다.',E('YU','자신에게 아무 영향을 ㉤ 주지 않는다고 느껴'),'P05.lexical_comparison','⑤ 결정')],
 [], 'NO는 도착·귀환·유래의 관계 차이를, YU는 중립/도움의 의미 성분 차이를 확인한다. 둘 다 문맥 치환이지만 교재에서 같은 단어 암기로 가르칠 수는 없다.')

g350_c='AYE'
passage('G350',[
 fun(g350_c,'기능 문단1: 가장 효율적인~','전체 조건의 동시 충족이라는 최적 기준을 세운 뒤, 일부 조건이 깨지면 조건 수의 증가로 전체 효율을 보장할 수 없다는 통념 반박을 제시한다. 목표는 깨지지 않은 조건의 무조건 보존이 아니라 제한 아래 새 조건 구성이다.','충족되는 효율성 조건의 수가 많아진다고 해서 경제 전체의 효율성이 더 향상된다는 보장이 없다는 것이다.'),
 fun(g350_c,'기능 문단2: 차선의 문제는 경제학 여러~','관세 일부 제거를 최적에 가까워짐으로 보는 주장에 대해 공급원 변경을 비용 상승/하락의 반대 효과로 분해한다. 순효과는 두 효과의 크기 비교에 달린다.','관세동맹이 세계 경제의 효율성을 증가시키는가의 여부는 무역창출 효과와 무역전환 효과 중 어느 것이 더 큰가에 달려 있다.'),
 fun(g350_c,'기능 문단3: 차선의 문제는 소득에~','상품 사이 상대 가격만 본 직접세 우위 주장을 여가 관련 교란으로 제한한다. 다음에는 같은 세액 아래 보완/경쟁 관계에 따라 차등 세율을 설계하는 대안을 제시한다.','직접세가 노동 시간과 여가에 영향을 미치지 않는다는 가정 아래서만 성립','직접세를 동일한 액수의 간접세로 대체하면서도')],
 {'AYE':'문단1의 조건 수와 효율의 불일치','AYF':'문단2의 공급원 비용 방향과 경쟁 주장','AYG':'문단1 적용 범위·문단3 학자별 주장·보기의 세 조건 성립 표'},
 ['AYF는 직접세/여가 기전을 쓰지 않음','AYE⑤ 단독 결정에는 보기 표·세액 고정 조건이 미사용','차등 세율의 구체적인 숫자·효율 함수는 원문에 없음'],
 [rel('P03','structure_present','공급원의 비용 방향 및 보완재 세금→소비→여가의 방향 연결이 제시되지만 최적 조건 수→효율의 단조 연결은 부정된다.',E(g350_c,'생산비용이 낮은 국가에서 생산비용이 높은 국가로 바꾸는 것이므로 효율이 감소','그 상품의 소비를 억제시킴으로써 여가의 소비도 줄이는 것이 가능')),
  rel('P04','structure_present','파레토 최적에는 모든 조건이 필요하고 직접세 우위 주장은 여가 무영향 가정에 의존한다. 모두 충족이라는 기준을 차선의 효율 순서로 확대하면 안 된다.',E(g350_c,'모든 최적 조건들이 동시에 충족되어야 한다.','직접세가 노동 시간과 여가에 영향을 미치지 않는다는 가정 아래서만'))],
 ['공통 passage_text는 기능 문단 세 개가 빈 줄 없이 합쳐져 있다. 위 위치명은 시작 문구로 정의한 기능 구간이며 원본 문단 번호로 가장하지 않는다.','AYE의 [시각 자료1]은 보기 표가 아니라 강조구 차선의 문제이다. emphasis_restored와 공식2·3쪽을 직접 확인했다.','AYG 보기의 ⇔/⇎와 네 열은 visual01/02 전사에서 중복·평탄화되어 있다. 공식3쪽 표를 직접 보고 열 대응을 확인했다.','공식 페이지2의 앞 지문 문항2·3은 화면에 부수 노출됐다. 검증 세트에 편입하거나 분석하지 않았다.'])

item('AYE',['기능 문단1 일부 조건 결손과 효율 비단조','문단2·3는 ③·④ 근거를 보강'],['보기 표와 직접/간접세 네 상황','관세 효과의 개별 사례 상세'],
 '전체 최적의 필요 요건과 차선 상태들 사이의 효율 순서는 다른 질문임을 인지한다.',
 '⑤는 비보장 명제를 비례 상승 보장으로 바꾸고 ①은 나머지 조건 충족이 차선 효율을 보장하지 않는다는 원래 한정을 유지한다.',
 '문단1의 조건 수가 많아져도 보장 없다는 문장과 ⑤ 직접 대조만으로 선택 가능하다.',
 ['충족 조건을 세어 점수처럼 효율을 매기지 않음','항상 효율 감소라고 역으로 일반화하지 않음'],[
 choice('AYE',1,'참','일부 결손 상태에 남은 조건의 충분성을 부정','조건 하나가 깨진 상태에서 다른 조건이 충족되어도 더 나음이 보장되지 않는다.','남은 최적 조건 충족이 차선의 최적 구성과 같지 않다.','차선 효율의 보장을 주장하지 않는다.','부적절 이해가 아니다.',['어떤 하나의 조건이 충족되지 않고 n-1개의 조건이 충족되는 상황','이러한 통념이 반드시 들어맞는 것은 아님']),
 choice('AYE',2,'참','차선 과제를 남은 조건 재구성으로 재진술','일부 조건 결손을 전제로 새로운 조건을 찾아야 한다.','기존에 성립한 조건도 무조건 보존 대상은 아니다.','재구성 고려가 과제와 맞는다.','부적절 이해가 아니다.',['현재 충족되고 있는 일부의 최적 조건들을 계속 유지하는 것이 과연 바람직한가','새로운 조건을 찾아야 한다는 과제']),
 choice('AYE',3,'참','부분 부문의 효율 감소 가능성과 전체 개선을 양립시킴','하나의 왜곡 시정이 새 왜곡을 초래할 수 있다.','전체 개선 과정에서도 기존 부문의 조건이 깨질 수 있다.','가능성에 한정한다.','부적절 이해가 아니다.',['하나의 왜곡을 시정하는 과정에서 새로운 왜곡이 초래되는 것이 일반적 현실']),
 choice('AYE',4,'지지되는 추론','부문 간 영향 연결을 차선 문제의 이유로 명시','한 왜곡의 시정이 다른 왜곡을 만들고 조세는 여가·상품 관계를 함께 바꾼다.','각 부문을 독립적으로 최적화한 결과가 전체 최적이라는 보장이 없다.','상호 연결은 두 사례로 뒷받침된다.','부적절 이해가 아니다.',['하나의 왜곡을 시정하는 과정에서 새로운 왜곡이 초래되는','직접세는 여가와 다른 상품들 사이의 파레토 최적 조건의 달성을 방해']),
 choice('AYE',5,'거짓','조건·왜곡 제거 개수에서 효율의 비례 증가로 일반화','성립 조건 수가 많아져도 전체 효율 향상은 보장되지 않는다.','부분 개선 개수는 전체 효과의 함수가 아니다.','비보장을 비례 보장으로 바꿨다.','선택한다.',['충족되는 효율성 조건의 수가 많아진다고 해서 경제 전체의 효율성이 더 향상된다는 보장이 없다는 것이다.'])],
 [rel('P03','경계·비적용','⑤에는 효율과 조건 수를 연결하는 정당한 방향 관계가 없으며 본문이 그 보장을 부정한다. 적용 예시로 세면 오적용이다.',E('AYE','충족되는 효율성 조건의 수가 많아진다고 해서 경제 전체의 효율성이 더 향상된다는 보장이 없다는 것이다.')),
  rel('P04','구조상 존재','전체 파레토 최적에는 모든 조건이 필요하다. 그러나 그 사실만으로 차선 상태들 사이 효율 순서를 결정하지 않는다.',E('AYE','모든 최적 조건들이 동시에 충족되어야 한다.')),
  rel('P02','경계·비적용','⑤의 오류를 막연히 축 혼동이라 이름 붙이면 원문이 부정한 효과 관계를 충분히 설명하지 못한다.',E('AYE','하나의 왜곡을 시정하는 과정에서 새로운 왜곡이 초래되는'))],
 ['R09'], '모든 조건 충족이 전체 최적에 필요하다는 기준과 충족 개수의 효율 순서는 다른 주장이다. 개선 보장 없음에서 악화 보장을 결론내리는 반대 오적용도 금지한다.')

item('AYF',['문단2 바이너의 효율 저하 가능성','무역전환의 공급원 비용 방향','각 선지의 전후 공급원·알려진 비용 관계'],['조세·여가 기전','차등 세율의 세액 고정'],
 '무역창출은 고비용→저비용, 무역전환은 저비용→고비용이라는 구별을 인지한다.',
 '②는 최저비용 C에서 비최저 B로 바뀌고 ③은 A와 B의 대소가 미정이라는 차이를 확인한다.',
 '②의 C 최저와 C→B 공급원 이동만 읽어 무역전환에 대입 가능하다.',
 ['관세율·운송비 숫자를 발명하지 않음','국내 생산 중단이나 동맹국 수입만으로 창출/전환을 확정하지 않음','바이너의 유일한 참을 증명했다고 표현하지 않음'],[
 choice('AYF',1,'지지 장면 없음','공급원 그대로인 사례 제시','효율 저하는 낮은 비용 공급원에서 높은 비용 공급원으로 바뀔 때 설명된다.','C에서 계속 수입하면 그 변화가 없다.','동맹의 감소 효과를 보여 주지 않는다.','선택하지 않는다.',['공급원을 생산비용이 낮은 국가에서 생산비용이 높은 국가로 바꾸는 것이므로 효율이 감소']),
 choice('AYF',2,'지지 사례로 적합','최저비용 비동맹 공급원을 동맹 공급원으로 변경','무역전환은 저비용에서 고비용 공급원으로 이동한다.','최저 C보다 B가 비싸며 A의 공급원이 C→B로 바뀐다.','항상 증가라는 주장에 반하는 감소 장면을 구현한다.','선택한다. 본문 비용 모형 안의 판단이다.',['무역전환은 공급원을 생산비용이 낮은 국가에서 생산비용이 높은 국가로 바꾸는 것이므로 효율이 감소']),
 choice('AYF',3,'판별 정보 부족','국내 생산에서 동맹국 수입으로 변경하되 필요한 대소 누락','감소 판단에는 전후 공급원의 비용 대소가 필요하다.','A와 B 모두 C보다 비싸다는 사실은 A와 B의 대소를 정하지 않는다.','A→B가 비용 상승인지 하락인지 미확정이다.','선택하지 않는다.',['생산비용이 높은 국가에서 생산비용이 낮은 국가','생산비용이 낮은 국가에서 생산비용이 높은 국가']),
 choice('AYF',4,'지지 장면 없음','최저 공급원 그대로인 사례 제시','효율 저하 주장은 공급원의 비용 상승 변화로 뒷받침된다.','B에서 계속 수입하여 변화가 없다.','감소 가능성을 보여 주는 장면이 없다.','선택하지 않는다.',['공급원을 생산비용이 낮은 국가에서 생산비용이 높은 국가로 바꾸는']),
 choice('AYF',5,'목표 주장 지지 아님','고비용 자국 생산에서 최저비용 동맹국 수입으로 이동','고비용→저비용은 무역창출에 따른 증가이다.','B 생산에서 최저 A 수입으로 전환한다.','증가 사례는 감소 가능성을 뒷받침하는 판별 사례가 아니다. 바이너 이론과 양립함과 지원 역할은 다르다.','선택하지 않는다.',['무역창출은 상품의 공급원을 생산비용이 높은 국가에서 생산비용이 낮은 국가로 바꾸는 것이기 때문에 효율이 증대'])],
 [rel('P03','적용','공급원 비용이라는 척도로 전후 방향을 읽는다. ③의 공통 상한/하한 관계는 두 대상의 대소를 결정하지 않는다.',E('AYF','생산비용이 낮은 국가에서 생산비용이 높은 국가로 바꾸는 것이므로 효율이 감소'),role='②의 변화 판단·③ 비교 유보'),
  rel('S02','경계·비적용','대안인 항상 증가와 목표인 감소 가능은 제시된다. 그러나 이는 관측 자료 선택이 아닌 가상 사례의 논증 역할 판정이다. discriminating_observation의 직접 반복으로 세지 않는다.',E('AYF','항상 세계 경제의 효율성을 증대','세계 경제의 효율성을 떨어뜨릴 수 있음'),'S02.discriminating_observation'),
  rel('P07','구조상 존재','관세동맹 전후는 있다. 핵심 판단은 사건 순서 교정보다 공급원 비용의 비교이다.',E('AYF','관세동맹을 맺기 이전에 비해'))],
 ['R04','R10'], '③의 A>C, B>C만으로 A>B는 나오지 않는다. A=12, B=10, C=5면 공급 비용은 내려가고 A=10, B=12, C=5면 올라간다. 둘 다 ③ 조건과 양립한다. 이는 ②의 최저 C→B와 다르다.')

item('AYG',['문단1 일부 조건 결손 아래의 차선 주장','문단3 학자별 조건·제안','공식3쪽 보기의 ㉮~㉱ 각 조건','강조구·표 기호 복원'],['관세의 생산비 수치·공급원 변경','레저용품이라는 예시 명칭 자체'],
 '핸더슨은 여가 무영향 가정, 리틀은 직접·간접 비교 유보, 콜레트/헤이그는 같은 세액의 차등 간접세 개선 가능성을 말한다.',
 '②의 ㉮→㉰는 전체 최적에서 결손으로의 차이이며 차선 상태들 사이의 조건 수/효율 비단조를 보이는 장면이 아니다. ④·⑤의 ㉱→㉰는 그 조건을 충족한다.',
 '문단1의 일부가 이미 깨진 상태라는 적용 범위를 ㉮와 비교하면 ②만 배제 가능하다. 표의 조건 개수는 관계 확인용이고 효율 점수가 아니다.',
 ['⇎ 개수가 적은 상태가 항상 효율적이라고 계산하지 않음','콜레트/헤이그의 가능성을 모든 차등 세율의 개선 보장으로 바꾸지 않음'],[
 choice('AYG',1,'참','학자 주장과 보기 세금 유형을 대응','핸더슨은 여가 영향을 고려하지 않고 직접세가 더 낫다고 본다.','㉰ 직접세와 ㉯ 단일 상품 간접세를 대조한다.','발언의 가정과 비교 방향을 보존한다.','부적절 대응이 아니다.',['직접세가 더 나을 것이라고 주장하는 ㉠핸더슨','직접세가 노동 시간과 여가에 영향을 미치지 않는다는 가정 아래서만']),
 choice('AYG',2,'논증 역할 부적합','전체 최적 대 결손 비교를 차선 비단조 주장의 근거로 이동','립시/랭커스터의 문제는 일부 조건이 이미 깨진 상태들 사이의 효율 보장이다.','㉮는 모든 조건이 성립하여 그 적용 범위에 있지 않다.','효율 차이가 있다고 해도 목표 주장에 필요한 비교 장면이 아니다. 리틀이 직접 그 비교로 주장했다는 근거도 없다.','선택한다.',['하나 이상의 효율성 조건이 이미 파괴되어 있는 상태에서는','㉡리틀은 주장하였다.']),
 choice('AYG',3,'참','비교 불가능 결론을 학자 비판에 연결','리틀은 직접/간접세 어느 쪽이 효율적인지 판단할 수 없다고 한다.','㉯·㉰는 깨지는 관계가 달라 조건 수만으로 우열을 정하지 못한다.','핸더슨 직접세 우위 가정을 비판하는 역할과 맞는다.','부적절 대응이 아니다.',['직접세가 더 효율적인지 간접세가 더 효율적인지를 판단할 수 없다는 것이다.']),
 choice('AYG',4,'참·가능성 한정','조건 수가 적은 상황의 개선 가능성을 목표 논증에 연결','차등 간접세가 직접세보다 효율을 높일 가능성을 제시한다.','㉱는 조건 성립 수가 ㉰보다 적어도 더 효율적일 수 있다.','조건 수의 단조 보장을 반박하는 장면이다.','부적절 대응이 아니다.',['여러 상품에 차등적 세율을 부과할 경우','효율성을 더 높일 수 있는 가능성이 있음을']),
 choice('AYG',5,'참·가능성 한정','같은 개선 장면을 직접/간접세 비교 사례로 연결','콜레트/헤이그는 직접세를 동일액 간접세로 대체하여 개선할 조건을 제시한다.','㉱의 차등 간접세가 ㉰의 직접세보다 나을 수 있다.','가능한 사례라는 범위를 유지한다.','부적절 대응이 아니다.',['직접세를 동일한 액수의 간접세로 대체하면서도','여가와 보완관계가 높은 상품에 높은 세율'])],
 [rel('P04','적용','②의 비교가 차선 문제를 입증하려면 이미 일부 조건이 깨진 상태들 사이의 비교여야 한다. ㉮는 범위 밖이다. 이는 누적 책임 요건과 다른 논증 적용 범위 하위 조작이다.',E('AYG','하나 이상의 효율성 조건이 이미 파괴되어 있는 상태에서는'),role='② 논증 범위 확인'),
  rel('P01','적용','①·③·④·⑤에서 다른 학자의 주장·가정·제안을 각 담당자와 보기 상태에 연결한다. ② 오류 전체를 귀속 교환만으로 설명하지 않는다.',E('AYG','㉠핸더슨','㉡리틀','㉢콜레트와 헤이그'),'P01.attribution','비정답 선지의 주장 귀속 검토'),
  rel('P03','경계·비적용','표의 성립 조건 수와 효율의 비교 방향이 정의로 연결되지 않는다. 수량 표라고 P03 비교 함수를 적용하면 안 된다.',E('AYG','효율성이 더 향상된다는 보장이 없다는 것이다.'))],
 ['R04','R09'], 'AYG④·⑤의 가능성은 원문 제안과 연결된다. 반면 ②는 최적→비최적 차이여서 차선 상태의 비단조를 입증하지 않는다. 내용 차이 존재와 목표 주장 지원은 별개이다.')

g350_table_quote='X ⇔ Y X ⇔ L Y ⇔ L | X ⇎ Y X ⇎ L Y ⇔ L | X ⇔ Y X ⇎ L Y ⇎ L | X ⇎ Y X ⇎ L Y ⇎ L'
table_e=ev('AYG',g350_table_quote,supplement='G350_visual01.md',note='공식2015 홀수형 인쇄3쪽 표를 직접 시각 확인; 네 열을 왼쪽부터 ㉮~㉱로 대조')
