def image_ev(name,region,observation,cases):
    path=ROOT/'자료/LEET_언어이해/HWP_홀수형_페이지_렌더링/2015'/name
    eid=f'EA{len(links)+1:04d}'
    links.append({'evidence_id':eid,'evidence_kind':'image_observation',
      'source_path':str(path.relative_to(ROOT)),'source_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),
      'printed_page':int(name[5:8]),'image_region_description':region,
      'observed_content_transcription':observation,
      'verification_limit':'현재 모델의 직접 시각 확인. 자동 검사에서는 이미지 해시·연결만 검증하며 전사의 의미·화소 일치는 검증하지 않음.'})
    for r in records:
        if r.get('case_id') in cases:
            r['evidence_ids'].append(eid)
            for ch in r['choice_analyses']:ch['evidence_ids'].append(eid)
        if r['record_type']=='passage_application' and r['group_id']=='G350':r['evidence_ids'].append(eid)

image_ev('page_002.png','왼쪽 아래 공통 지문 첫 문단 마지막의 사각 강조구',
         '차선(次善)의 문제',['AYE'])
image_ev('page_003.png','왼쪽 위 문항4 발문',
         '4. 차선의 문제에 대한 이해로 적절하지 않은 것은?',['AYE'])
image_ev('page_003.png','오른쪽 위 문항6 보기 표; 열 왼쪽부터 ㉮·㉯·㉰·㉱',
         '㉮ 무세금: XY·XL·YL 모두⇔; ㉯ X간접세: XY⇎·XL⇎·YL⇔; ㉰ 직접세: XY⇔·XL⇎·YL⇎; ㉱ XY차등간접세: XY·XL·YL 모두⇎. ⇔는 파레토 최적 조건 성립, ⇎는 비성립.',['AYG'])

# 관계 이름과 코드북 원래 관계를 함께 보존한다. 활용은 필수·유일 경로를 뜻하지 않는다.
for r in records:
    for a in r['pattern_decisions']:
        d=a['decision']
        if d=='structure_present':a['decision']='구조상 존재';d='구조상 존재'
        a['codebook_relations']={'적용':['item_utilized','solution_helpful'],
           '구조상 존재':['structure_present'],'불확실':['unconfirmed'],
           '경계·비적용':['boundary_case']}[d]
        a['structure_mode']='설명' if r['group_id']=='G095' and a['pattern_id']=='P04' else '구현'
        if a['structure_mode']=='설명' and d=='구조상 존재':a['codebook_relations'].append('explanatory_only')
        a['necessary_for_all_solutions']=False
    if r['record_type']=='item_application':
        r['unclassified_scenes']=[{'residual_candidate_id':x,'relation':'unclassified'} for x in r['residual_candidate_ids']]
        for x in r['not_applicable_patterns']:
            x['decision']='비적용';x['codebook_relation']=None;x['count_as_occurrence']=False

def dump_jsonl(path,rows):path.write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))
dump_jsonl(OUT/'case_annotations.jsonl',records)
dump_jsonl(OUT/'evidence_links.jsonl',links)

